#include <bits/stdc++.h>
using namespace std;

using ll = long long;
using vi = vector<ll>;
using pi = pair<ll, ll>;
const ll MOD = 1000000007;

bool isPrime(unsigned long long n) {
    if (n <= 1) return true;
    if (n <= 3) return true;
    if (n % 2 == 0 || n % 3 == 0) return false;
    for (unsigned long long i = 5; i * i <= n; i += 6)
        if (n % i == 0 || n % (i + 2) == 0)
            return false;
    return true;
}

ll modPow(ll base, ll exp, ll mod) {
    ll result = 1;
    base %= mod;
    while (exp > 0) {
        if (exp & 1) result = (result * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return result;
}

ll nCr(int n, int k) {
    if (k > n) return 0;
    if (k > n - k) k = n - k;
    ll res = 1;
    for (int i = 0; i < k; ++i) {
        res *= (n - i);
        res /= (i + 1);
    }
    return res;
}

void solve() {
    string s;
    cin >> s;
    int n = s.length();
    vector<bool> processed(n, false);
    processed[0] = true;
    cout << s[0];

    bool atReplaced = false;
    for (int i = 1; i <= n - 3; ++i) {
        processed[i] = true;
        if (!atReplaced && s[i] == 'a' && s[i+1] == 't') {
            cout << '@';
            atReplaced = true;
            processed[i+1] = true;
            ++i;
        } else if (i < n - 2 && s[i] == 'd' && s[i+1] == 'o' && s[i+2] == 't') {
            cout << '.';
            processed[i+1] = true;
            processed[i+2] = true;
            i += 2;
        } else {
            cout << s[i];
        }
    }

    for (int i = 0; i < n; ++i) {
        if (!processed[i]) cout << s[i];
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    #ifndef ONLINE_JUDGE
    freopen("in.txt", "r", stdin);
    freopen("op.txt", "w", stdout);
    #endif

    int t = 1;
    while (t--) solve();
    return 0;
}
